export function waveToDataUrl(primaryColor: string, secondaryColor: string) {
	const svgString = `
    <svg xmlns="http://www.w3.org/2000/svg" width="631" height="364" viewBox="0 0 631 364" fill="${primaryColor}" opacity="0.4">
      <path d="${path1D}" fill="${secondaryColor}" />
      <path d="${path2D}" fill="${secondaryColor}" />
    </svg>
  `

	const toBase64 = (str: string) =>
		typeof window === 'undefined' ? Buffer.from(str).toString('base64') : window.btoa(str)

	return { wave: `data:image/svg+xml;base64,${toBase64(svgString)}` }
}
